/**
 * Rules shared by the browser renderer and the server renderer, so a value
 * is treated the same way whichever one draws it.
 */

/** Attributes whose value is a URL the browser will navigate to or load. */
export const URL_ATTRIBUTES: ReadonlySet<string> = new Set(["href", "src", "action", "formaction", "xlink:href", "poster"]);

/** The most characters `safeUrl` reads, enough for the longest prefix it checks, `data:image/x-icon;`. */
const CHECKED_LENGTH = 24;

/**
 * True when a URL may be assigned to a navigating or loading attribute.
 * Only the scheme decides, so it reads the first characters that are not
 * spaces or control characters and stops, whatever the URL's length.
 */
export function safeUrl(value: string): boolean
{
    let scheme = "";
    for (const character of value)
    {
        if (character > " ")
        {
            scheme += character;
            if (scheme.length === CHECKED_LENGTH)
            {
                break;
            }
        }
    }
    scheme = scheme.toLowerCase();
    if (scheme.startsWith("javascript:") || scheme.startsWith("vbscript:"))
    {
        return false;
    }
    if (scheme.startsWith("data:"))
    {
        return /^data:image\/(?:png|gif|jpeg|jpg|webp|avif|bmp|x-icon)[;,]/.test(scheme);
    }
    return true;
}

/** Joins the static strings of an attribute value with its resolved values; null and undefined read as empty. */
export function join(strings: readonly string[], values: readonly unknown[]): string
{
    let text = strings[0] ?? "";
    for (let i = 0; i < values.length; i++)
    {
        const value = values[i];
        text += (value === null || value === undefined ? "" : String(value)) + (strings[i + 1] ?? "");
    }
    return text;
}

/** Names a value's type for diagnostics. */
export function describe(value: unknown): string
{
    if (typeof value === "function")
    {
        return "function";
    }
    if (value === null)
    {
        return "null";
    }
    if (typeof value === "object")
    {
        return value.constructor?.name ?? "object";
    }
    return typeof value;
}

/** True for values that render as nothing. */
export function isNothing(value: unknown): value is null | undefined | boolean
{
    return value === null || value === undefined || typeof value === "boolean";
}

/** True for values that render as text. */
export function isText(value: unknown): value is string | number | bigint
{
    return typeof value === "string" || typeof value === "number" || typeof value === "bigint";
}
